import{_ as d,o as r,c as o,ag as a}from"./chunks/framework.KxDd3USm.js";const b=JSON.parse('{"title":"02.6 事务、并发控制与故障恢复 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"02-数据库系统/06-事务并发与故障恢复.md","filePath":"02-数据库系统/06-事务并发与故障恢复.md"}'),n={name:"02-数据库系统/06-事务并发与故障恢复.md"};function e(s,t,l,g,h,i){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="_02-6-事务、并发控制与故障恢复-★★" tabindex="-1">02.6 事务、并发控制与故障恢复 ★★ <a class="header-anchor" href="#_02-6-事务、并发控制与故障恢复-★★" aria-label="Permalink to &quot;02.6 事务、并发控制与故障恢复 ★★&quot;">​</a></h1><h3 id="事务与-acid" tabindex="-1">事务与 ACID <a class="header-anchor" href="#事务与-acid" aria-label="Permalink to &quot;事务与 ACID&quot;">​</a></h3><p>事务是&quot;要么全做、要么全不做&quot;的一组操作。经典例子：转账 = A 扣 100 + B 加 100，两个 UPDATE 必须同生共死。</p><table tabindex="0"><thead><tr><th>性质</th><th>含义</th><th>靠什么保证</th></tr></thead><tbody><tr><td>原子性 Atomicity</td><td>全做或全不做</td><td>故障恢复（UNDO）</td></tr><tr><td>一致性 Consistency</td><td>事务前后数据都处于正确状态</td><td>原子性 + 隔离性共同效果</td></tr><tr><td>隔离性 Isolation</td><td>并发事务互不干扰</td><td>并发控制（锁）</td></tr><tr><td>持久性 Durability</td><td>提交后永久生效</td><td>故障恢复（REDO/日志）</td></tr></tbody></table><p>考法：&quot;转账中途断电，钱不能凭空消失&quot;体现<strong>原子性</strong>；&quot;提交后断电重启数据仍在&quot;体现<strong>持久性</strong>。</p><h3 id="并发带来的四类错误-反例各背一个" tabindex="-1">并发带来的四类错误（反例各背一个） <a class="header-anchor" href="#并发带来的四类错误-反例各背一个" aria-label="Permalink to &quot;并发带来的四类错误（反例各背一个）&quot;">​</a></h3><p>两个事务 T1、T2 同时操作 A=100：</p><ol><li><strong>丢失修改</strong>：T1 和 T2 都读 A=100，T1 加 10 写回 110，T2 减 5 写回 95——T1 的修改被<strong>覆盖丢了</strong>（应是 105）。</li><li><strong>不可重复读</strong>：T1 读 A=100，T2 把 A 改成 200 并提交，T1 再读 A 变 200——<strong>同一事务内两次读结果不同</strong>。</li><li><strong>读脏数据</strong>：T1 把 A 改成 200（还没提交），T2 读到 200；T1 随后<strong>回滚</strong>，A 恢复 100——T2 读到的 200 是&quot;脏&quot;的，根本没生效过。</li><li><strong>幻读</strong>：T1 第一次查询“成绩≥90 的学生”得到 3 行；T2 插入一名 95 分学生并提交；T1 用同一条件再查得到 4 行——像凭空多出一行“幻影”。</li></ol><p>不可重复读与幻读都表现为“两次查询不同”，区别在对象：前者是<strong>已有同一行的字段值变了</strong>，后者是<strong>满足条件的行数增减了</strong>。口诀：<strong>丢改是写被盖，脏读是读未交，不可重复是同一行变，幻读是结果集增减行。</strong></p><h3 id="封锁与两段锁协议" tabindex="-1">封锁与两段锁协议 <a class="header-anchor" href="#封锁与两段锁协议" aria-label="Permalink to &quot;封锁与两段锁协议&quot;">​</a></h3><ul><li><strong>S 锁（共享锁/读锁）</strong>：持锁事务可以读，其他事务还可加 S 锁一起读，但不能加 X 锁写。</li><li><strong>X 锁（排他锁/写锁）</strong>：持锁事务可以读写，其他事务不能再加 S 或 X 锁。</li></ul><p>相容矩阵必须会看：行表示“已有锁”，列表示“新申请锁”。</p><table tabindex="0"><thead><tr><th>已有锁 \\ 新申请</th><th style="text-align:right;">S 锁</th><th style="text-align:right;">X 锁</th></tr></thead><tbody><tr><td>S 锁</td><td style="text-align:right;">相容</td><td style="text-align:right;">不相容</td></tr><tr><td>X 锁</td><td style="text-align:right;">不相容</td><td style="text-align:right;">不相容</td></tr></tbody></table><ul><li><strong>两段锁协议</strong>：事务分两阶段——先<strong>扩展阶段</strong>（只加锁不放锁），后<strong>收缩阶段</strong>（只放锁不加锁）。一旦释放了第一把锁，就不能再申请新锁。</li><li>遵守两段锁协议 → 调度<strong>可串行化</strong>，即并发结果等价于某一种串行顺序执行；但它<strong>不能避免死锁</strong>。</li></ul><p>反例：T1 先锁 A 再等 B，T2 先锁 B 再等 A，两者都处于扩展阶段、都可能符合两段锁，却形成循环等待。因此固定结论是：<strong>两段锁保证可串行化，不保证不死锁。</strong></p><p>选择题若给出调度并问是否可串行化，简化做法是尝试把所有冲突操作的先后关系画成“事务箭头”：若 T1 必须在 T2 前，同时又推出 T2 必须在 T1 前，形成环，就不能等价为串行调度；无环则可按拓扑顺序串行化。</p><h3 id="故障恢复-先分故障-再定-redo-undo" tabindex="-1">故障恢复：先分故障，再定 REDO/UNDO <a class="header-anchor" href="#故障恢复-先分故障-再定-redo-undo" aria-label="Permalink to &quot;故障恢复：先分故障，再定 REDO/UNDO&quot;">​</a></h3><table tabindex="0"><thead><tr><th>故障类型</th><th>题干识别词</th><th>影响范围</th><th>主要恢复手段</th></tr></thead><tbody><tr><td>事务故障</td><td>单个事务越界、死锁被撤销、逻辑错误</td><td>某个事务</td><td>利用日志 UNDO 该事务</td></tr><tr><td>系统故障</td><td>断电、操作系统崩溃、数据库进程崩溃</td><td>内存内容丢失，磁盘通常未坏</td><td>从检查点和日志执行 REDO/UNDO</td></tr><tr><td>介质故障</td><td>磁盘损坏、盘块不可读、数据库文件毁坏</td><td>持久化数据受损</td><td>装入备份，再用归档日志 REDO</td></tr></tbody></table><p><strong>反例演示（易错）</strong>：断电通常属于系统故障，不等于磁盘介质已经损坏；“磁盘磁头损坏导致数据文件不可读”才是介质故障。系统故障靠日志即可恢复，介质故障必须先有备份作底。</p><p>依靠<strong>日志</strong>（先写日志、后写数据库）+ <strong>检查点</strong>。系统重启后扫描日志：</p><ul><li>事务<strong>已提交</strong>（BEGIN 后有 COMMIT）→ <strong>REDO 重做</strong>（结果应该生效，重放保证落盘）；</li><li>事务<strong>未提交</strong>（只有 BEGIN 没有 COMMIT）→ <strong>UNDO 撤销</strong>（做了一半的必须抹掉）。</li></ul><p>口诀：<strong>提交了就重做（REDO），没提交就撤销（UNDO）</strong>。检查点的作用是记录当时的恢复起点和活跃事务，使恢复时不必从日志开头全量扫描；不能机械理解为“检查点之前的一切都不用管”，跨越检查点但尚未结束的事务仍要结合日志处理。</p><p>日志片段若显示 T1 有 <code>COMMIT</code>、T2 只有 <code>BEGIN</code> 和若干写操作，那么恢复动作就是 <strong>REDO T1、UNDO T2</strong>。反向核对语义：提交的结果必须保持，未提交的半成品必须消失。</p><h3 id="分布式数据库-四特性与四种透明性" tabindex="-1">分布式数据库：四特性与四种透明性 <a class="header-anchor" href="#分布式数据库-四特性与四种透明性" aria-label="Permalink to &quot;分布式数据库：四特性与四种透明性&quot;">​</a></h3><p>先分清两类问题：“系统本身有什么特点”问<strong>特性</strong>；“用户不必知道什么细节”问<strong>透明性</strong>。</p><table tabindex="0"><thead><tr><th>特性</th><th>白话含义</th><th>题干识别词</th></tr></thead><tbody><tr><td>共享性</td><td>各站点的数据能被全局用户共享</td><td>跨节点共同访问数据</td></tr><tr><td>自治性</td><td>每个站点能独立管理本地数据库</td><td>本地独立控制、独立运行</td></tr><tr><td>可用性</td><td>某站点故障时可使用其他站点或副本继续服务</td><td>单点故障后系统仍可用</td></tr><tr><td>分布性</td><td>数据物理存放在网络中的多个场地</td><td>多节点、不同地域存储</td></tr></tbody></table><p>四种透明性则按“用户被屏蔽的细节”识别：</p><table tabindex="0"><thead><tr><th>透明性</th><th>用户不必知道</th><th>关键词</th></tr></thead><tbody><tr><td>分片透明（最高层）</td><td>一张全局表如何横向或纵向分块</td><td>分片、分块规则</td></tr><tr><td>复制透明</td><td>同一数据复制了几份、更新哪些副本</td><td>副本、复制份数</td></tr><tr><td>位置透明</td><td>数据或副本位于哪个站点</td><td>地址、节点、场地位置</td></tr><tr><td>局部映像透明/逻辑透明（最低层）</td><td>局部 DBMS 的数据模型和操作语言</td><td>异构数据库、模型转换</td></tr></tbody></table><p><strong>易错对比</strong>：“表被怎样切成几块”是分片透明；“某一块放在哪座机房”是位置透明；“同一块存了三份”是复制透明。不要把“分片”误当成物理位置。</p><p><strong>应试动作</strong>：ACID 四个词背全称；四类并发错误能看描述对号入座；S/X 锁只记住“S-S 唯一相容”；“两段锁 → 可串行化但可能死锁”背成一句；故障题先分事务/系统/介质，再套 REDO/UNDO；分布式题先判断问的是“特性”还是“透明性”。</p>',30)])])}const T=d(n,[["render",e]]);export{b as __pageData,T as default};
